## Why This Is Asked
This question assesses multi-cloud Terraform patterns, per-tenant isolation, provider aliasing, and governance gates in CI/CD pipelines. It evaluates practical module layout decisions and backend scoping across tenants.

## Key Concepts
- Terraform provider aliases for AWS and GCP
- Per-tenant workspace and backend isolation
- Cross-cloud networking with consistent tagging enforcement
- CI gates to enforce tenant targeting and environment boundaries

## Code Example
```hcl
# snippet: environment map
variable "tenants" {
  type = map(object({
    cloud  = string
    region = string
    environment = string
  }))
  default = {
    "tenant-a" = {
      cloud       = "aws"
      region      = "us-east-1"
      environment = "prod"
    }
    "tenant-b" = {
      cloud       = "gcp"
      region      = "us-west1"
      environment = "staging"
    }
  }
}

# snippet: wrapper module structure
# modules/tenant-workspace/main.tf
variable "tenant_name" {}
variable "tenant_config" {}

terraform {
  backend "s3" {
    key = "tenants/${var.tenant_name}/terraform.tfstate"
  }
}

module "networking" {
  source         = "../shared/cross-cloud-networking"
  tenant_name    = var.tenant_name
  cloud_provider = var.tenant_config.cloud
  region         = var.tenant_config.region
  tags = merge(var.tenant_config.tags, {
    Tenant      = var.tenant_name
    Environment = var.tenant_config.environment
    ManagedBy   = "terraform"
  })
}

# snippet: cross-cloud networking
# modules/shared/cross-cloud-networking/main.tf
variable "tenant_name" {}
variable "cloud_provider" {}
variable "region" {}
variable "tags" {}

locals {
  required_tags = ["Tenant", "Environment", "ManagedBy"]
}

resource "aws_vpc" "tenant" {
  count = var.cloud_provider == "aws" ? 1 : 0
  cidr_block           = "10.${index(keys(var.tags))}.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true
  tags = merge(var.tags, {
    Name = "${var.tenant_name}-vpc"
  })
}

resource "google_compute_network" "tenant" {
  count = var.cloud_provider == "gcp" ? 1 : 0
  name                    = "${var.tenant_name}-vnet"
  auto_create_subnetworks = false
  description             = "Tenant network for ${var.tenant_name}"
}

# snippet: CI gate script
#!/bin/bash
# ci/gate-tenant-deploy.sh
set -euo pipefail

BACKEND_ENV=$(echo "$TF_WORKSPACE" | cut -d'-' -f1)
TENANT_NAME=$(echo "$TF_WORKSPACE" | cut -d'-' -f2)

validate_backend_env() {
  local tenant_cloud backend_env target_env
  tenant_cloud=$(jq -r ".tenants.\"${TENANT_NAME}\".cloud // empty" "$ENV_MAP")
  backend_env=$(echo "$TF_WORKSPACE" | grep -oP '^\w+(?=-)')

  if [[ "$backend_env" == "prod" && "$TENANT_NAME" != *"-prod" ]]; then
    echo "ERROR: Prod backend cannot target non-prod tenant"
    exit 1
  fi

  if [[ -n "$tenant_cloud" && "$tenant_cloud" != "$CLOUD_PROVIDER" ]]; then
    echo "ERROR: Tenant cloud mismatch. Expected: $tenant_cloud, Got: $CLOUD_PROVIDER"
    exit 1
  fi
}

validate_backend_env
```

## Common Pitfalls
- Forgetting to scope backends per tenant, causing state collisions
- Missing required tags, leading to untagged resources in production
- Not validating tenant-to-cloud mappings before applying changes
- Overlooking provider alias configuration for cross-cloud modules

